//! Embeds the Godrays icon in the Windows executable, so Explorer, the
//! taskbar and shortcuts show it. The icon file is generated by the app
//! itself: `godrays --export-icon assets/godrays.ico`.

fn main() {
    println!("cargo:rerun-if-changed=assets/godrays.ico");
    #[cfg(windows)]
    {
        let windows_target = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows");
        if windows_target && std::path::Path::new("assets/godrays.ico").exists() {
            let mut resource = winresource::WindowsResource::new();
            resource.set_icon("assets/godrays.ico");
            if let Err(error) = resource.compile() {
                // Not fatal: the window still sets its own icon at runtime.
                println!("cargo:warning=icon not embedded in the .exe: {error}");
            }
        }
    }
}
